```tsx
import { useId } from "react";
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps) {
  const titleId = useId();
  const detailId = useId();
  const minutesId = useId();

  const rowClass = done
    ? "checklist-item checklist-item--done"
    : "checklist-item";

  return (
    <div className={rowClass}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-labelledby={titleId}
        aria-describedby={`${detailId} ${minutesId}`}
        onClick={onToggle}
      >
        <svg
          className="checklist-item__tick"
          viewBox="0 0 16 16"
          aria-hidden="true"
          focusable="false"
        >
          <path d="M3.5 8.5l3 3 6-7" />
        </svg>
      </button>

      <div className="checklist-item__text">
        <p id={titleId} className="checklist-item__title">
          {title}
        </p>
        <p id={detailId} className="checklist-item__detail">
          {detail}
        </p>
      </div>

      <span id={minutesId} className="checklist-item__minutes">
        {minutes} min
      </span>
    </div>
  );
}
```

