.checklist-item {
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 2vw, 1rem);
  padding: clamp(0.6rem, 1.5vw, 0.9rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.checklist-item__check {
  flex: none;
  inline-size: clamp(1.75rem, 4vw, 2.25rem);
  block-size: clamp(1.75rem, 4vw, 2.25rem);
  padding: 0;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid var(--muted);
  background: transparent;
  color: transparent;
  font: inherit;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.checklist-item__check:hover {
  background: var(--myelin-wash);
  border-color: var(--myelin);
}

/* Declared after :hover so the filled state wins while hovered. */
.checklist-item__check[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
  color: var(--slide);
}

.checklist-item__tick {
  inline-size: 55%;
  block-size: 55%;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.checklist-item__text {
  flex: 1;
  min-inline-size: 0;
  display: grid;
  gap: 0.2rem;
}

.checklist-item__title {
  margin: 0;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.95rem, 0.9rem + 0.3vw, 1.1rem);
  overflow-wrap: anywhere;
  transition: color 150ms ease;
}

.checklist-item__detail {
  margin: 0;
  color: var(--muted);
  font: inherit;
  font-size: clamp(0.8rem, 0.76rem + 0.2vw, 0.9rem);
  overflow-wrap: anywhere;
}

.checklist-item__minutes {
  flex: none;
  color: var(--muted);
  font-size: clamp(0.8rem, 0.76rem + 0.2vw, 0.9rem);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.checklist-item--done .checklist-item__title {
  color: var(--muted);
  text-decoration: line-through;
}

:root[data-motion="reduce"] .checklist-item__check,
:root[data-motion="reduce"] .checklist-item__title {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item__check,
  .checklist-item__title {
    transition: none;
  }
}
